const orderDetail = input.orderDetail || {};
const returnItems = input.refund_items || [];

const orderMap = {};
const keys = ['deliveredGroups', 'toDeliverGroups', 'returnedGroups'];
for (let i = 0; i < keys.length; i++) {
  const groups = orderDetail[keys[i]] || [];
  for (let j = 0; j < groups.length; j++) {
    const items = (groups[j] && groups[j].items) || [];
    for (let k = 0; k < items.length; k++) {
      const item = items[k] || {};
      const barCode = String(item.barCode || item.barcode || '').trim();
      if (!barCode) continue;
      let qty = Number(
        item.itemCount != null ? item.itemCount : item.quantity != null ? item.quantity : 1,
      );
      if (!isFinite(qty)) qty = 1;
      orderMap[barCode] = (orderMap[barCode] || 0) + qty;
    }
  }
}

const returnMap = {};
for (let r = 0; r < returnItems.length; r++) {
  const ri = returnItems[r] || {};
  const rb = String(ri.barCode || ri.barcode || '').trim();
  if (!rb) continue;
  let rq = Number(
    ri.returnedCount != null ? ri.returnedCount : ri.itemCount != null ? ri.itemCount : 1,
  );
  if (!isFinite(rq)) rq = 1;
  returnMap[rb] = (returnMap[rb] || 0) + rq;
}

const orderBarCodes = Object.keys(orderMap);
const returnBarCodes = Object.keys(returnMap);

let solution = null;
if (orderBarCodes.length && returnBarCodes.length) {
  let returnAll = true;
  for (let o = 0; o < orderBarCodes.length; o++) {
    const code = orderBarCodes[o];
    if ((returnMap[code] || 0) < orderMap[code]) {
      returnAll = false;
      break;
    }
  }
  if (returnAll) {
    for (let t = 0; t < returnBarCodes.length; t++) {
      if (!orderMap[returnBarCodes[t]]) {
        returnAll = false;
        break;
      }
    }
  }
  solution = returnAll ? 'RETURN_AND_REFUND' : 'PARTIAL_REFUND';
}

return { solution };

