const products=input.refund_items;
let productType = null;
let sameProductType = products.length > 0;

for (const product of products) {
  const sku = String(product.sku || '').trim().toUpperCase();
  const currentType = sku.startsWith('USAIS')
    ? 'aisin'
    : sku.startsWith('USPA')
      ? 'pa'
      : 'inHouse';

  if (productType === null) {
    productType = currentType;
  } else if (currentType !== productType) {
    sameProductType = false;
  }
}

return {
  sameProductType,
  productType: sameProductType ? productType : 'mixed'
};

